window.togglePassword=function(){const t=document.getElementById("password"),e=document.getElementById("eyeIcon");!t||!e||(t.type==="password"?(t.type="text",e.classList.replace("ph-eye","ph-eye-slash")):(t.type="password",e.classList.replace("ph-eye-slash","ph-eye")))};window.switchRole=function(t){const e=document.getElementById("tabSiswa"),n=document.getElementById("tabOrtu"),o=document.getElementById("roleInput"),s=document.getElementById("submitBtn");o.value=t,t==="siswa"?(e.className="flex-1 py-3 text-sm font-semibold rounded-xl transition-all duration-300 bg-white text-[#4A90E2] shadow-sm cursor-pointer",n.className="flex-1 py-3 text-sm font-semibold rounded-xl transition-all duration-300 text-[#6b7280] hover:text-[#4A90E2] cursor-pointer",s.innerText="Masuk Sebagai Siswa"):(n.className="flex-1 py-3 text-sm font-semibold rounded-xl transition-all duration-300 bg-white text-[#4A90E2] shadow-sm cursor-pointer",e.className="flex-1 py-3 text-sm font-semibold rounded-xl transition-all duration-300 text-[#6b7280] hover:text-[#4A90E2] cursor-pointer",s.innerText="Masuk Sebagai Orang Tua")};document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("loginForm");t&&t.addEventListener("submit",function(){const e=document.getElementById("submitBtn");e.innerHTML='<i class="ph ph-spinner ph-spin mr-2"></i> Memproses...',e.classList.add("opacity-80","cursor-not-allowed")})});
